"@

$riderTargets = @()
foreach ($p in $AllPages) {
    $route = Get-RoutePath $p.FullName
    if (@("/rider/my-tasks", "/rider/dashboard", "/rider-dashboard", "/rider/tasks") -contains $route) {
        $c = Get-Content -LiteralPath $p.FullName -Raw
        if (-not ($c -match "/api/rider-login")) { $riderTargets += $p.FullName }
    }
}

if ($riderTargets.Count -eq 0) {
    $riderTargets += (Join-Path $AppDir "rider\my-tasks\page.tsx")
}

foreach ($t in $riderTargets) {
    if ($t -notlike "*.tsx") {
        $bk = Join-Path $BackupDir ($t.Substring($Root.Length).TrimStart("\"))
        New-Item -ItemType Directory -Force -Path (Split-Path $bk) | Out-Null
        Move-Item -LiteralPath $t -Destination $bk -Force
        $t = [IO.Path]::ChangeExtension($t, ".tsx")
    }
    Write-TextFile $t $RiderWrapper
}
Say "  OK      Rider page ready:  localhost:3000/rider/my-tasks" Green

