# ---------- v29: Security secret keys (.env) ----------
# Login cookies are signed with these keys. Without them anyone could fake an admin login.
Say ""
Say "v29: Security keys (.env)..." White
function New-F2CSecret {
    $b = New-Object byte[] 36
    [System.Security.Cryptography.RandomNumberGenerator]::Create().GetBytes($b)
    return ([Convert]::ToBase64String($b) -replace '[+/=]', 'x')
}
$EnvMain = Join-Path $Root ".env"
$EnvLocal = Join-Path $Root ".env.local"
foreach ($key in @("FRESH2COOK_AUTH_SECRET", "RIDER_SESSION_SECRET")) {
    $done = $false
    foreach ($file in @($EnvLocal, $EnvMain)) {
        if (-not (Test-Path -LiteralPath $file)) { continue }
        $text = [System.IO.File]::ReadAllText($file)
        $rx = "(?m)^[ \t]*" + $key + "[ \t]*=[ \t]*[""']?([^""'\r\n]*)[""']?[ \t]*(?=\r?$)"
        $m = [regex]::Match($text, $rx)
        if (-not $m.Success) { continue }
        if ($m.Groups[1].Value.Trim().Length -ge 32) {
            Say "  OK      $key pehle se theek hai ($([System.IO.Path]::GetFileName($file)))" Green
        } else {
            $bk = Join-Path $BackupDir ([System.IO.Path]::GetFileName($file))
            [void][System.IO.Directory]::CreateDirectory($BackupDir)
            [System.IO.File]::Copy($file, $bk, $true)
            $text = $text.Remove($m.Index, $m.Length).Insert($m.Index, "$key=" + (New-F2CSecret))
            [System.IO.File]::WriteAllText($file, $text, $Utf8NoBom)
            Say "  UPDATE  $key chhota tha, naya strong key lagaya ($([System.IO.Path]::GetFileName($file)))" Yellow
        }
        $done = $true
        break
    }
    if (-not $done) {
        $text = ""
        if (Test-Path -LiteralPath $EnvMain) {
            $text = [System.IO.File]::ReadAllText($EnvMain)
            $bk = Join-Path $BackupDir ".env"
            [void][System.IO.Directory]::CreateDirectory($BackupDir)
            [System.IO.File]::Copy($EnvMain, $bk, $true)
        }
        if ($text.Length -gt 0 -and -not $text.EndsWith("`n")) { $text += "`r`n" }
        $text += "$key=" + (New-F2CSecret) + "`r`n"
        [System.IO.File]::WriteAllText($EnvMain, $text, $Utf8NoBom)
        Say "  NEW     $key .env me add kiya (secret key - kisi ko na dikhayein)" Yellow
    }
}
# private KYC folder + keep secrets out of git
[void][System.IO.Directory]::CreateDirectory((Join-Path $Root "private-uploads"))
$GitIgnore = Join-Path $Root ".gitignore"
if (Test-Path -LiteralPath $GitIgnore) {
    $gi = [System.IO.File]::ReadAllText($GitIgnore)
    $extra = ""
    foreach ($l in @(".env", ".env.local", "private-uploads/", "_backups/")) {
        if ($gi -notmatch ("(?m)^" + [regex]::Escape($l) + "\s*$")) { $extra += "`r`n" + $l }
    }
    if ($extra) { [System.IO.File]::WriteAllText($GitIgnore, $gi.TrimEnd() + $extra + "`r`n", $Utf8NoBom); Say "  UPDATE  .gitignore (.env, private-uploads)" Green }
}
Say "  OK      Har API par login check, KYC documents private folder me" Green

# ---------- v31: Faster development server (Turbopack) ----------
$PkgPath = Join-Path $Root "package.json"
if (Test-Path -LiteralPath $PkgPath) {
    $pkg = [System.IO.File]::ReadAllText($PkgPath)
    if ($pkg -match '"dev"\s*:\s*"next dev"') {
        $bk = Join-Path $BackupDir "package.json"
        [void][System.IO.Directory]::CreateDirectory($BackupDir)
        [System.IO.File]::Copy($PkgPath, $bk, $true)
        $pkg = [regex]::Replace($pkg, '"dev"\s*:\s*"next dev"', '"dev": "next dev --turbopack",' + "`r`n" + '    "dev:old": "next dev"', 1)
        [System.IO.File]::WriteAllText($PkgPath, $pkg, $Utf8NoBom)
        Say "  UPDATE  package.json: npm run dev ab Turbopack se (2-3 guna tez)" Green
    } elseif ($pkg -match 'next dev --turbopack') {
        Say "  OK      npm run dev pehle se Turbopack par hai" Green
    }
}

# --- Database: nayi tables (AppSetting, CustomerAccount) ---
# Ab yeh tables app khud pehli baar use hone par bana leta hai (prisma generate ki zaroorat nahi).
# schema.prisma me models sirf record ke liye add kiye jaate hain.
$SchemaPath = Join-Path $Root "prisma\schema.prisma"
if (Test-Path $SchemaPath) {
    $schemaText = Get-Content -LiteralPath $SchemaPath -Raw
    if ($schemaText -notmatch "model\s+AppSetting\s*\{" -or $schemaText -notmatch "model\s+CustomerAccount\s*\{") {
        $bk = Join-Path $BackupDir "prisma\schema.prisma"
        New-Item -ItemType Directory -Force -Path (Split-Path $bk) | Out-Null
        Copy-Item -LiteralPath $SchemaPath -Destination $bk -Force
        $add = $Utf8NoBom.GetString([Convert]::FromBase64String(($B64_SCHEMA_ADD -join "")))
        [System.IO.File]::WriteAllText($SchemaPath, $schemaText.TrimEnd() + "`r`n" + $add, $Utf8NoBom)
        Say "  UPDATE  prisma\schema.prisma (AppSetting, CustomerAccount)" Green
    }
}
Say "  OK      Settings + Customer tables pehli baar page khulte hi apne aap ban jayengi" Green

